changeSet.sql:
UPDATE variable_setting vs set vs.label = 'Salaire de base', vs.description = 'Salaire de base' WHERE vs.key = 'BASE_SALARY';
UPDATE variable_setting vs set vs.label = 'Nombre de jours', vs.description = 'Nombre de jours' WHERE vs.key = 'DAYS_NBR';
UPDATE variable_setting vs set vs.label = 'Nombre de jours ouvrables', vs.description = 'Nombre de jours ouvrables' WHERE vs.key = 'WORKING_DAYS_NBR';
UPDATE variable_setting vs set vs.label = "Nombre d'heures'Nombre d'heure", vs.description = "Nombre d'heures" WHERE vs.key = 'HOURS_NBR';
UPDATE variable_setting vs set vs.label = 'Jours par semaine', vs.description = 'Jours par semaine' WHERE vs.key = 'DAYS_BY_WEEK';
UPDATE variable_setting vs set vs.label = 'Heures par semaine', vs.description = 'Heures par semaine' WHERE vs.key = 'HOURS_BY_WEEK';
INSERT INTO `variable_setting` (`key`, `label`, `description`, `company_id`)
SELECT distinct 'IRG(BASE)','Retenue IRG', 'Retenue IRG', `company_id` FROM `section_category`;
